import{_ as t,o as a,c as s,ah as n}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Re-enrollments","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/reinscriptions.md","filePath":"src/en/guide/admin/reinscriptions.md"}'),r={name:"en/guide/admin/reinscriptions.md"};function o(i,e,l,h,c,d){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="re-enrollments" tabindex="-1">Re-enrollments <a class="header-anchor" href="#re-enrollments" aria-label="Permalink to &quot;Re-enrollments&quot;">​</a></h1><p>Once the <a href="/era-guide/en/guide/admin/decisions-fin-annee.html">year-end decisions</a> are taken, re-enroll students into the next year, class by class: those who move up into a class of the next level, those who repeat into a class of the same level. ERA creates a <strong>new enrollment</strong> for each of them in the new year; their enrollment in the past year, with its grades, bulletins and payments, stays untouched.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ol><li><strong>Create and prepare the next year</strong>: its classes and fee structures (see <a href="/era-guide/en/guide/admin/structure-etablissement.html#preparing-the-next-year">Preparing the next year</a>). Add the classes that didn&#39;t exist yet, e.g. the final-year classes the current top classes move up into.</li><li><strong>Check the levels</strong>: every class of the past year and of the new year needs its level (see <a href="/era-guide/en/guide/admin/structure-etablissement.html#levels">Levels</a>).</li><li><strong>Take the year-end decisions</strong>: a student without a decision is not re-enrolled.</li></ol><h2 id="re-enrolling-a-class" tabindex="-1">Re-enrolling a class <a class="header-anchor" href="#re-enrolling-a-class" aria-label="Permalink to &quot;Re-enrolling a class&quot;">​</a></h2><ol><li>Open <strong>Students &amp; admissions → Re-enrollments</strong>.</li><li>Choose <strong>From</strong> (the past year), <strong>To</strong> (the new year) and the <strong>Class</strong>. The class list shows how many students remain to place.</li><li>Students are grouped by decision: <ul><li><strong>Moving up to …</strong>: choose their class in the new year, among classes of the next level on the same site;</li><li><strong>Repeating …</strong>: choose their class among classes of the same level.</li></ul></li><li>Click <strong>Re-enroll n students into …</strong>.</li></ol><p>When only one class fits, it is already selected. When several do, ERA selects the one sharing the source class&#39;s <strong>series</strong> if there is one; otherwise, choose.</p><p>Not re-enrolled:</p><ul><li>students who <strong>leave the school</strong>, and students who pass the school&#39;s last level;</li><li>students <strong>without a decision</strong>: a <strong>Decide now</strong> link leads to their class&#39;s decisions;</li><li>students <strong>already enrolled</strong> in the new year, e.g. placed by hand: they are never moved. Running the re-enrollment again is therefore safe.</li></ul><h2 id="what-follows-the-student" tabindex="-1">What follows the student <a class="header-anchor" href="#what-follows-the-student" aria-label="Permalink to &quot;What follows the student&quot;">​</a></h2><ul><li>Their <strong>specialty subjects</strong> are carried into the new enrollment when the new class still offers them as a choice. Their personal coefficient is kept within the same department; in another department, that department&#39;s coefficient applies.</li><li>Their <strong>optional fees</strong> (cafeteria, transport…) are not carried over: the family chooses them again every year. The cashier sees last year&#39;s and can pick them again in one click, see <a href="/era-guide/en/guide/caissier/inscriptions-et-paiements.html#setting-the-fees-due">Enrollments and payments</a>.</li></ul><h2 id="unpaid-balances" tabindex="-1">Unpaid balances <a class="header-anchor" href="#unpaid-balances" aria-label="Permalink to &quot;Unpaid balances&quot;">​</a></h2><p>Each student who still owes money for the past year is marked <strong>Unpaid</strong> with the remaining amount. Re-enrollment is <strong>not blocked</strong>: the balance is settled at the cash desk.</p><h2 id="capacity" tabindex="-1">Capacity <a class="header-anchor" href="#capacity" aria-label="Permalink to &quot;Capacity&quot;">​</a></h2><p>If a chosen class would go over its capacity, tick <strong>Go over the capacity of …</strong> (the checkbox names the class) to re-enroll anyway.</p><h2 id="afterwards" tabindex="-1">Afterwards <a class="header-anchor" href="#afterwards" aria-label="Permalink to &quot;Afterwards&quot;">​</a></h2><ul><li>A student placed in the wrong class is moved with a <a href="/era-guide/en/guide/secretariat/changements-de-classe.html">class change</a> in the new year; a student changing site goes through a <a href="/era-guide/en/guide/secretariat/transferts-sites.html">site transfer</a>.</li><li>A re-enrolled student&#39;s decision can no longer be changed or cancelled: the decisions page shows &quot;Re-enrolled in …&quot;.</li><li>When the new school year starts, switch the current year with <strong>Set as current</strong> under <strong>School setup → Academic years</strong>.</li></ul><div class="tip custom-block"><p class="custom-block-title">New students</p><p>New students come in through <a href="/era-guide/en/guide/secretariat/candidatures.html">applications</a>: an application approved in June can already go into a class of the next year.</p></div>',18)])])}const p=t(r,[["render",o]]);export{g as __pageData,p as default};
